$eventSql="SELECT e.*,r.read_at FROM team_inbox_events e LEFT JOIN team_inbox_reads r ON r.event_id=e.event_id AND r.user_id=? WHERE e.audience IN ('all',?, 'staff')";$eventArgs=[$uid,$role];
if($filters['event']!==''){$eventSql.=' AND e.event_type=?';$eventArgs[]=$filters['event'];}
if(($_GET['unread']??'')==='1')$eventSql.=' AND r.read_at IS NULL';
$eventSql.=' ORDER BY e.created_at DESC LIMIT 150';$eventStmt=$pdo->prepare($eventSql);$eventStmt->execute($eventArgs);$events=$eventStmt->fetchAll();
function inboxBadgeClass(string $status): string { return match($status){'new','active','hired','resolved'=>'text-bg-success','reviewing','open','scheduled'=>'text-bg-primary','interview','waiting'=>'text-bg-warning','offered'=>'text-bg-info','rejected','withdrawn','closed','paused','ended'=>'text-bg-secondary',default=>'text-bg-light'}; }
function inboxEventBadgeClass(string $type): string { return match(true){str_contains($type,'promo')=>'text-bg-success',str_contains($type,'application')=>'text-bg-info',str_contains($type,'contact')||str_contains($type,'feedback')=>'text-bg-warning',str_contains($type,'order')=>'text-bg-primary',default=>'text-bg-secondary'}; }
